export type RealVacancy = {
  id: string;
  portalTitle: string;
  title: string;
  categorySlug: string;
  categoryName: string;
  image: string;
  location: string;
  salary: string;
  schedule: string;
  summary: string;
  description: string;
  applyUrl: string;
};

function stripLoneSurrogates(value: string): string {
  return value.replace(/[\uD800-\uDBFF][\uDC00-\uDFFF]|[\uD800-\uDFFF]/g, (match) =>
    match.length === 2 ? match : "",
  );
}

export function buildVacancyWhatsAppShareUrl(vacancy: Pick<RealVacancy, "title" | "location" | "salary" | "applyUrl">): string {
  const lines = [
    `Oportunidade de trabalho na MaZa Empregos: *${vacancy.title}*`,
    `Local: ${vacancy.location}`,
    vacancy.salary ? `Remuneração: ${vacancy.salary}` : "",
    `Candidate-se gratuitamente pelo portal oficial: ${vacancy.applyUrl}`,
  ].filter(Boolean);
  return `https://api.whatsapp.com/send/?text=${encodeURIComponent(stripLoneSurrogates(lines.join("\n")))}`;
}

